Item.method_code:
            Aras.ConversionFramework.Models.ConversionTask task = new Aras.ConversionFramework.Models.ConversionTask()
            {
                Item = this
            };
            Innovator inn = this.getInnovator();
            try
            {
                String docQuery = @"
                <AML>
                <Item type='Document' action='get'>
                <file_item>" + task.FileID + @"</file_item>
                </Item>
                </AML>";
                Item res = inn.applyAML(docQuery);
                if (res.isError())
                {
                    throw new Exception(res.getErrorString());
                }
                task.AddDependency(res);
            }
            catch (Exception ex)
            {
                return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
            }

            return task.Item;
        }
